  window.LESSONS["u3_l10"] = {"meta":{"grade":3,"subject":"과학","term":2,"unit":3,"unit_title":"소리의 성질","n":10,"covers":"10차시","title":"소리의 성질 (단원 마무리)","goal":"〰️ 소리가 나는 물체의 떨림을 정리해요. / 🎼 소리의 세기와 높낮이를 정리해요. / 🧱 소리의 전달과 소음 줄이기 방법을 정리해요.","std":"[4과07-01][4과07-02][4과07-03]","duration_min":40,"lesson_format":"단원 마무리 · 2세대 19장(7요소)","theme":"곰이·펭이 소리 탐험대","live_url":"../../grade3/semester2/science/3단원_소리의성질/g3_sci_u3_l10_단원마무리.html","source":"grade3/semester2/science/3단원_소리의성질/g3_sci_u3_l10_단원마무리.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"소리의 성질 — 마무리\n떨림 · 세기 · 높낮이 · 전달 · 소음 줄이기","emoji":"🏆"},"suggested_extras":["v_l9_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 여러 개의 마이크로 **소리가 나는 곳을 색깔로** 보여 주는 음향 카메라와, 인공지능으로 고장 난 곳을 빠르게 찾는 쓰임을 알았어요.","items":[{"q":"음향 카메라는 무엇을 색깔로 나타내나요?","a":"소리가 나는 곳"},{"q":"화면의 색깔은 소리의 무엇에 따라 달라지나요?","a":"세기와 높낮이"},{"q":"인공지능 음향 카메라로 할 수 있는 일은 무엇인가요?","a":"섞인 소리 속에서 고장 난 곳의 소리를 빠르게 찾는다"}],"from":"u3_l09"},"suggested_extras":["q_l9_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"소리 탐험대 결산","kids":[{"face":"🐻","label":"곰이\n\"떨림·세기·높낮이·전달·소음… 다 기억나?\""},{"face":"🐧","label":"펭이\n\"정리 카드를 하나씩 열어 확인해 보자. 헷갈리면 그 쪽으로 돌아가면 돼!\""}],"question":"펭이는 **정리 카드**로 하나씩 확인하자고 해요. 소리의 성질에서 배운 다섯 가지를 한눈에 정리하려면 무엇부터 떠올리면 좋을까요?","img":"assets/photo/science/sound_summary.jpg","tnote":{"ask":["이 단원에서 배운 것을 세 가지만 말하면?","헷갈리는 내용은 어떻게 하나요?"],"watch":"「다 기억난다」로 넘기는 경우 — 카드로 확인","min":3}},"suggested_extras":["q_l9_2","r_l9_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"emoji":"〰️","name":"소리의","kind":"발생"},{"emoji":"🎼","name":"세기와","kind":"높낮이"},{"emoji":"🧱","name":"전달과","kind":"소음"}]},"title":"이 단원의 흐름","content":"잘 떠오르지 않으면 **표시한 쪽**으로 돌아가 확인해요.","tnote":{"ask":["이 단원의 흐름 세 갈래는?","잘 떠오르지 않으면 어떻게 하나요?"],"watch":"순서를 섞어 말하는 경우 — 발생 → 세기·높낮이 → 전달·소음","min":4}},"src":2,"suggested_extras":["e_l9_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"chain","items":[{"emoji":"〰️","name":"떨림","kind":"소리가 나는 물체는 떨림이 있어요"},{"emoji":"🔊","name":"소리의 세기","kind":"소리의 크고 작은 정도예요"},{"emoji":"🎼","name":"소리의 높낮이","kind":"소리의 높고 낮은 정도예요"},{"emoji":"🧱","name":"소리의 전달","kind":"소리는 고체, 액체, 기체 상태의 여러 가지 물질을 통해 전달돼요"},{"emoji":"🔇","name":"소음 줄이기","kind":"불쾌하고 시끄러운 소리를 소음이라고 해요"},{"emoji":"✏️","name":"과학 글쓰기","kind":"공사장 소리가 너무 커서 대화하기 어려워요"}]},"title":"정리 카드를 열어 확인해요","content":"단원의 정리 카드예요. 차례로 열며 헷갈리는 카드를 찾아봐요.","tnote":{"ask":["소리의 세기는 무엇에 따라 달라지나요?","소음을 줄이는 두 가지 방법은?"],"watch":"세기와 높낮이 카드를 바꿔 말하는 경우 — 떨림 / 길이","min":5}},"src":3,"suggested_extras":["t_l9_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"sort2","q":"옳은 설명인가?","a":{"name":"○ 옳아요","items":["〰️ 소리가 나는 물체는 떨림이 있어요","🥁 물체가 크게 떨리면 큰 소리가 나요","🧱 방음벽으로 소음을 줄일 수 있어요"]},"b":{"name":"✗ 옳지 않아요","items":["🔊 크고 작은 정도를 높낮이라고 해요","🎹 짧은 음판을 치면 낮은 소리가 나요","☁️ 소리는 기체로만 전달돼요"],"hint":"옳지 않은 설명은 **바르게 고쳐** 말해요"}},"title":"설명을 나눠 확인해요","content":"「옳은 설명인가?」로 나눴어요. 옳지 않은 설명은 옳게 고쳐 말해 봐요.","tnote":{"ask":["옳지 않은 설명은 무엇인가요?","「짧은 음판을 치면 낮은 소리」를 바르게 고치면?"],"watch":"옳지 않은 설명을 그대로 외우는 경우 — 고쳐 말하기","min":4}},"src":4,"suggested_extras":["e_l9_2","t_l9_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"emoji":"〰️","name":"소리를 내고","kind":"떨림 설명하기"},{"emoji":"🎼","name":"세기와 높낮이가","kind":"다른 소리 내기"},{"emoji":"🧱","name":"소리의 전달 관찰과","kind":"소음 줄이기 실천"}]},"title":"나는 이만큼 할 수 있어요","content":"색칠하며 성취 수준을 확인하고, 잘 떠오르지 않는 내용은 **해당 쪽**으로 돌아가 다시 살펴봐요.","tnote":{"ask":["세 가지 중 자신 있는 것은?","다시 살펴볼 것은 무엇인가요?"],"watch":"전부 색칠하고 확인하지 않는 경우 — 정직하게","min":4}},"src":5,"suggested_extras":["q_l9_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"세게 치면 북면이 크게 떨리며 작은 소리가 날까요?","label":"자주 하는 생각","wrong":"세게 치면 크게 떨리며 **작은 소리**가 난다.","right":"아니에요! 세게 치면 크게 떨리면서 **큰 소리**, 약하게 치면 작게 떨리면서 **작은 소리**가 나요. 🥁\n헷갈리면 『과학』 64~65쪽으로 돌아가 **작은북 실험**을 다시 살펴봐요.","hint":"작은북 실험(64~65쪽)을 다시 떠올리게 하세요 — 크게 떨림 = 큰 소리.","tnote":{"ask":["세게 치면 북면은 어떻게 떨리나요?","크게 떨리면 어떤 소리가 나나요?"],"watch":"떨림의 크기와 소리의 세기를 반대로 잇는 경우","min":3}},"src":6,"suggested_extras":["x_l9_1","x_l9_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🎼","body":"곰이가 설명을 세기와 높낮이 통에 나눠요.\n나눌 것: 〰️ 크게 떨리면 큰 소리 · 🎹 짧은 음판은 높은 소리 · 🤏 약하게 치면 작은 소리 · 🎶 긴 관은 낮은 소리\n통: 🔊 소리의 세기 · 🎼 소리의 높낮이"},"question":"세기일까요, 높낮이일까요?","answer":"🔊 소리의 세기 — 크게 떨리면 큰 소리 · 약하게 치면 작은 소리 / 🎼 소리의 높낮이 — 짧은 음판은 높은 소리 · 긴 관은 낮은 소리","note":"풀이: 길이는 높낮이, 떨림의 크기는 세기예요."},"src":"p1","suggested_extras":["t_l9_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🎵","body":"펭이가 칼림바 음판을 보며 물었어요.\n칼림바의 음판은 길이가 서로 달라요."},"question":"칼림바의 가장 낮은 소리는?","options":[{"text":"가장 짧은 음판"},{"text":"가운데 음판"},{"text":"아무 음판이나"},{"text":"가장 긴 음판","correct":true}],"note":"풀이: 긴 물체는 낮은 소리가 나요. → **가장 긴 음판**"},"src":"p2","suggested_extras":["e_l9_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🔗","body":"상황과 물질의 상태를 짝지어요.\n왼쪽: 🥤 실 전화기 목소리 · 🔊 물속 스피커 소리 · 🐦 새소리\n오른쪽: 고체 · 액체 · 기체"},"question":"상황과 물질의 상태를 짝지어요","answer":"🥤 실 전화기 목소리 ↔ 고체 / 🔊 물속 스피커 소리 ↔ 액체 / 🐦 새소리 ↔ 기체","note":"풀이: 실은 고체, 물은 액체, 공기는 기체예요."},"src":"p3","suggested_extras":["q_l9_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"소리가 나는 물체의 특징과 소음을 줄이는 방법 두 가지를 말해 봐요.","a":"떨림이 있다 — 세기 줄이기 · 잘 전달되지 않게 하기","steps":["소리굽쇠 관찰을 떠올린다","소음 줄이는 두 갈래를 떠올린다","차례로 말한다"]},"도전":{"q":"「크게 떨리면 높은 소리가 난다」는 설명이 옳지 않은 까닭을 말하고 바르게 고쳐 봐요.","a":"떨림의 크기는 세기를 정한다 — 크게 떨리면 큰 소리가 난다 (높낮이는 길이)","steps":["떨림의 크기가 정하는 것을 떠올린다","길이가 정하는 것을 떠올린다","바르게 고쳐 말한다"]},"심화":{"q":"내가 지휘자가 되어 오케스트라에게 「더 크게」와 「더 높게」를 지시한다면 연주자들은 각각 무엇을 바꿔야 하는지 말해 봐요.","a":"여러 답 (예: 더 크게 = 더 세게 켜거나 불어 크게 떨리게 · 더 높게 = 더 짧은 음판·짧은 줄로)","open":true}},"tnote":{"ask":["기본에서 두 갈래가 다 나왔나요?","도전에서 떨림 → 세기로 고쳤나요?"],"watch":"심화에서 「크게 = 높게」로 답하는 경우 — 두 말 나누기","min":5}},"suggested_extras":["q_l9_5","g_l9_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"소리 탐험대 퀴즈 대회","type":"group","goal":"모둠에서 정리 카드로 소리의 성질 문제를 세 개 만들어 다른 모둠과 주고받으며 답하고, 틀린 문제는 되돌아갈 쪽을 함께 찾기","steps":["정리 카드 다섯 장을 펼친다","카드마다 문제를 하나씩 만들어 종이에 쓴다","다른 모둠과 문제를 바꿔 답한다","틀린 문제는 되돌아갈 쪽을 찾아 다시 읽는다"],"solo":["정리 카드마다 문제를 하나씩 만들어 공책에 쓴다","답을 가리고 스스로 풀어 본 뒤 맞힌 수를 쓴다"],"materials":["정리 카드","종이","펜"],"minutes":8,"tnote":{"ask":["어떤 카드 문제가 어려웠나요?","틀린 문제는 어디로 돌아갔나요?"],"watch":"답만 외우고 까닭을 못 대는 경우 — 까닭 묻기","min":8}},"suggested_extras":["g_l9_2","t_l9_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"지휘자와 오케스트라","scenario":{"icon":"🎼","body":"지휘자는 손짓으로 연주자들에게 「더 크게」·「더 작게」를 알려요. 연주자는 활을 세게 켜거나 숨을 세게 불어 **떨림을 크게** 하고, 높은 음은 **짧은 줄·짧은 관**으로 내요. 소리의 세기와 높낮이가 어우러져 음악이 돼요."},"content":"음악은 소리의 **세기와 높낮이**를 다루는 일이에요."},"suggested_extras":["r_l9_2","r_l9_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"공사장 소리가 너무 커서 옆 학교 아이들이 대화하기 어렵다는 글을 읽었어요.","challenge":"이 문제를 소리의 성질로 설명하고, 소음을 줄이는 방법을 두 갈래에서 하나씩 제안하는 짧은 글을 써 봐요.","note":"풀이: 공사장의 큰 소리는 **공기**를 통해 학교까지 전달돼요. **방음벽**을 세우면 소리가 잘 전달되지 않고(전달 막기), 소리가 큰 기계를 쓰는 시간을 정하거나 조용한 기계를 쓰면 **소리의 세기**가 줄어요(세기 줄이기).","tnote":{"ask":["공사장 소리는 무엇을 통해 오나요?","두 갈래에서 하나씩 제안하면?"],"watch":"한 갈래만 제안하는 경우 — 세기와 전달 둘 다","min":3}},"suggested_extras":["t_l9_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"소리가 나는 물체의 공통점은 무엇인가요?","a":"떨림이 있다"},{"q":"떨림의 크기와 물체의 길이는 각각 소리의 무엇을 정하나요?","a":"떨림의 크기 → 세기 · 길이 → 높낮이"},{"q":"소음을 줄이는 방법 두 가지를 말하면 무엇인가요?","a":"소리의 세기 줄이기 · 소리가 잘 전달되지 않게 하기"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["소리가 나는 물체는 **떨림**이 있어요.","떨림의 크기에 따라 **세기**가, 길이에 따라 높낮이가 달라요.","소리는 여러 물질로 전달되고, **소음**은 줄일 수 있어요.","곰이와 펭이는 정리 카드 다섯 장으로 퀴즈를 주고받고, 옳지 않은 설명을 바르게 고치며 소리 탐험대를 마쳤다."],"arrows":["떨림 → 소리의 발생","떨림 크기 = 세기 · 길이 = 높낮이","고체·액체·기체로 전달 · 소음은 줄인다"]},"suggested_extras":["r_l9_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 소리의 성질에서 배운 것을 정리할 수 있나요?","🔧 과정·기능 — 옳지 않은 설명을 찾아 바르게 고칠 수 있나요?","💛 가치·태도 — 잘 떠오르지 않는 내용을 정직하게 표시하고 다시 살펴봤나요?"],"prompts":["소리의 성질에서 배운 것을 정리할 수 있나요?"]},"suggested_extras":["e_l9_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"이 단원을 마쳐요","preview":"🎼 내가 지휘자가 된다면 어떤 **소리**를 지휘해 보고 싶나요?","emoji":"🎶"},"suggested_extras":["c_l9_1"]}],"extras":[{"id":"v_l9_1","type":"video","icon":"🎥","title":"소리의 성질 정리 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+3%ED%95%99%EB%85%84+2%ED%95%99%EA%B8%B0+%EA%B3%BC%ED%95%99+%EC%86%8C%EB%A6%AC%EC%9D%98+%EC%84%B1%EC%A7%88+%EB%8B%A8%EC%9B%90+%EC%A0%95%EB%A6%AC+%EB%96%A8%EB%A6%BC+%EC%84%B8%EA%B8%B0+%EB%86%92%EB%82%AE%EC%9D%B4+%EC%A0%84%EB%8B%AC+%EC%86%8C%EC%9D%8C","description":"단원 전체를 되짚는 정리 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l9_1","type":"fun_question","icon":"💡","title":"떨림","content":"소리가 나는 물체의 공통점은?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_2","type":"fun_question","icon":"💡","title":"칼림바","content":"칼림바의 가장 긴 음판은 어떤 소리일까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_3","type":"fun_question","icon":"💡","title":"잠수부","content":"바닷속 배 소리는 무엇을 통해 오나요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_4","type":"fun_question","icon":"💡","title":"고쳐 말하기","content":"「짧은 음판은 낮은 소리」를 어떻게 고칠까요?","fit_slides":["concept","basic_problem"]},{"id":"q_l9_5","type":"fun_question","icon":"💡","title":"지휘자","content":"지휘자가 된다면 어떤 소리를 지휘하고 싶나요?","fit_slides":["concept","basic_problem"]},{"id":"t_l9_1","type":"tip","icon":"🧩","title":"카드 차례","content":"정리 카드는 단원 흐름 차례로 여세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_2","type":"tip","icon":"🧩","title":"되돌아갈 쪽","content":"교과서 쪽수를 함께 보여 주세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_3","type":"tip","icon":"🧩","title":"정직한 색칠","content":"자기 평가는 정직하게 색칠하게 하세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_4","type":"tip","icon":"🧩","title":"두 말 나누기","content":"세기·높낮이를 마지막으로 나눠 적으세요.","fit_slides":["concept","misconception"]},{"id":"t_l9_5","type":"tip","icon":"🧩","title":"다음 단원","content":"다음 단원 준비물을 미리 안내하세요.","fit_slides":["concept","misconception"]},{"id":"r_l9_1","type":"real_world","icon":"🌍","title":"지휘자","content":"지휘자는 세기와 높낮이를 지휘해요.","fit_slides":["real_world","summary"]},{"id":"r_l9_2","type":"real_world","icon":"🌍","title":"공사장","content":"공사장 주위 방음벽은 전달을 막아요.","fit_slides":["real_world","summary"]},{"id":"r_l9_3","type":"real_world","icon":"🌍","title":"악기","content":"악기마다 길이로 높낮이를 내요.","fit_slides":["real_world","summary"]},{"id":"g_l9_1","type":"game","icon":"🎮","title":"퀴즈 대회","content":"정리 카드로 문제를 만들어 주고받아요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l9_2","type":"game","icon":"🎮","title":"고쳐 말하기","content":"옳지 않은 설명을 바르게 고쳐요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l9_1","type":"misconception","icon":"⚠️","title":"크게 = 작게","content":"세게 치면 작은 소리가 난다는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l9_2","type":"misconception","icon":"⚠️","title":"기체로만","content":"소리가 기체로만 전달된다는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l9_1","type":"example","icon":"📝","title":"세 갈래","content":"소리의 발생·세기와 높낮이·전달과 소음 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l9_2","type":"example","icon":"📝","title":"정리 카드","content":"떨림·세기·높낮이·전달·소음 줄이기·글쓰기 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l9_3","type":"example","icon":"📝","title":"스스로 평가","content":"세 칸 색칠 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l9_1","type":"checklist","icon":"✅","title":"다음 단원 준비","content":"다음 단원 준비물을 안내해요.","fit_slides":["next_lesson"]}]};
